#!/usr/bin/env bash
# TK-493 S2: дымовая проба команд волн на ФОРМИРОВАНИИ (cd ~/xdl9/sel/waves; bash ../smoke_cmds.sh)
set -u
THREADS=${THREADS:-8}
tj() { seq -s, 0 $(( $(wc -l < "$1") - 2 )); }
mkdir -p smoke_out smoke_d2
: > smoke_out/smoke.log
: > smoke_out/d2_diff.log
echo '== A2' >> smoke_out/smoke.log
$HOME/xdl9/bin/statarb-xdl9-a24f4c96-pgo statarb run --kind pair --panels $HOME/xdl9/form/aster --funding-y $HOME/xdl9/funding_form/aster --rearm --cells sigma/A2_aster_crypto.cells.csv --jobs sigma/A2_aster_crypto__aster__aster.jobs.csv --daily-out smoke_out/A2_aster_crypto__aster__aster.daily.csv --trades-out smoke_out/A2_aster_crypto__aster__aster.trades.csv --trades-ext --trade-jobs "$(tj sigma/A2_aster_crypto__aster__aster.jobs.csv)" --open-out smoke_out/A2_aster_crypto__aster__aster.open.csv --mtm-open --cells-out smoke_out/A2_aster_crypto__aster__aster.cells_out.csv --ext-out smoke_out/A2_aster_crypto__aster__aster.ext.csv --job-ext-out smoke_out/A2_aster_crypto__aster__aster.jobext.csv --job-day-out smoke_out/A2_aster_crypto__aster__aster.jobday.csv --min-span 1440 --threads ${THREADS:-8} >> smoke_out/smoke.log 2>&1 && echo OK A2 >> smoke_out/smoke.log || echo FAIL A2 >> smoke_out/smoke.log
echo '== C1' >> smoke_out/smoke.log
$HOME/xdl9/bin/statarb-xdl9-a24f4c96-pgo statarb run --kind cross --panels $HOME/xdl9/form/aster --panels-b $HOME/xdl9/form/okx --funding-y $HOME/xdl9/funding_form/aster --funding-x $HOME/xdl9/funding_form/okx --delay-x 1 --rearm --cells sigma/C1_aster~okx_crypto_w64.cells.csv --jobs sigma/C1_aster-okx_crypto_w64__aster__okx.jobs.csv --daily-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.daily.csv --trades-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.trades.csv --trades-ext --trade-jobs "$(tj sigma/C1_aster-okx_crypto_w64__aster__okx.jobs.csv)" --open-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.open.csv --mtm-open --cells-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.cells_out.csv --ext-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.ext.csv --job-ext-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.jobext.csv --job-day-out smoke_out/C1_aster-okx_crypto_w64__aster__okx.jobday.csv --min-span 1440 --threads ${THREADS:-8} >> smoke_out/smoke.log 2>&1 && echo OK C1 >> smoke_out/smoke.log || echo FAIL C1 >> smoke_out/smoke.log
echo '== D2' >> smoke_out/smoke.log
python3 $HOME/xdl9/tools/statarb/xdl9/d2_diff_funding.py --pairs w1/D2_aster-binance_crypto__binance__aster.pairs.csv --fund-y $HOME/xdl9/funding_form/binance --fund-x $HOME/xdl9/funding_form/aster --out smoke_d2/D2_aster-binance_crypto__binance__aster --from-day 2465 --to-day 2479 >> smoke_out/d2_diff.log && for J in smoke_d2/D2_aster-binance_crypto__binance__aster/shard*.jobs.csv; do S=$(basename $J .jobs.csv); [ $(wc -l < $J) -gt 1 ] || continue; $HOME/xdl9/bin/statarb-xdl9-a24f4c96-pgo statarb run --kind funding-pp --panels $HOME/xdl9/form/binance --panels-b $HOME/xdl9/form/aster --funding-y smoke_d2/D2_aster-binance_crypto__binance__aster/$S --funding-x smoke_d2/D2_aster-binance_crypto__binance__aster/empty_x --rule funding --funding-k 6 --hold-payments 2 --cell "D2|aster~binance|crypto|a0" --window 60 --min-obs 60 --entry-z 1.00 --exit-z 0 --stop-z inf --max-hold 0 --refresh 60 --jobs $J --no-entry-before-from --min-span 1440 --threads ${THREADS:-8} --daily-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.daily.csv --trades-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.trades.csv --trades-ext --trade-jobs "$(tj $J)" --open-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.open.csv --mtm-open --cells-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.cells_out.csv --ext-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.ext.csv --job-ext-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.jobext.csv --job-day-out smoke_out/D2_aster-binance_crypto__binance__aster__$S.jobday.csv; done >> smoke_out/smoke.log 2>&1 && echo OK D2 >> smoke_out/smoke.log || echo FAIL D2 >> smoke_out/smoke.log
echo '== A1' >> smoke_out/smoke.log
$HOME/xdl9/bin/statarb-xdl9-a24f4c96-pgo statarb run --kind pair --panels $HOME/xdl9/form/binance --funding-y $HOME/xdl9/funding_form/binance --rearm --cells sigma/A1_binance_crypto.cells.csv --jobs sigma/A1_binance_crypto__binance__binance.jobs.csv --daily-out smoke_out/A1_binance_crypto__binance__binance.daily.csv --trades-out smoke_out/A1_binance_crypto__binance__binance.trades.csv --trades-ext --trade-jobs "$(tj sigma/A1_binance_crypto__binance__binance.jobs.csv)" --open-out smoke_out/A1_binance_crypto__binance__binance.open.csv --mtm-open --cells-out smoke_out/A1_binance_crypto__binance__binance.cells_out.csv --ext-out smoke_out/A1_binance_crypto__binance__binance.ext.csv --job-ext-out smoke_out/A1_binance_crypto__binance__binance.jobext.csv --job-day-out smoke_out/A1_binance_crypto__binance__binance.jobday.csv --min-span 1440 --threads ${THREADS:-8} >> smoke_out/smoke.log 2>&1 && echo OK A1 >> smoke_out/smoke.log || echo FAIL A1 >> smoke_out/smoke.log
echo '== B1' >> smoke_out/smoke.log
$HOME/xdl9/bin/statarb-xdl9-a24f4c96-pgo statarb run --kind basket --panels $HOME/xdl9/form/binance --funding-y $HOME/xdl9/funding_form/binance --rearm --cells sigma/B1_binance_crypto.cells.csv --jobs sigma/B1_binance_crypto__binance__binance.jobs.csv --daily-out smoke_out/B1_binance_crypto__binance__binance.daily.csv --trades-out smoke_out/B1_binance_crypto__binance__binance.trades.csv --trades-ext --trade-jobs "$(tj sigma/B1_binance_crypto__binance__binance.jobs.csv)" --open-out smoke_out/B1_binance_crypto__binance__binance.open.csv --mtm-open --cells-out smoke_out/B1_binance_crypto__binance__binance.cells_out.csv --ext-out smoke_out/B1_binance_crypto__binance__binance.ext.csv --job-ext-out smoke_out/B1_binance_crypto__binance__binance.jobext.csv --job-day-out smoke_out/B1_binance_crypto__binance__binance.jobday.csv --min-span 1440 --threads ${THREADS:-8} >> smoke_out/smoke.log 2>&1 && echo OK B1 >> smoke_out/smoke.log || echo FAIL B1 >> smoke_out/smoke.log
